CREATE TABLE IF NOT EXISTS schema_versions(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT OR IGNORE INTO schema_versions VALUES(1,datetime('now'));
CREATE TABLE IF NOT EXISTS cases(id TEXT PRIMARY KEY,name TEXT NOT NULL,customer TEXT NOT NULL,mode TEXT NOT NULL DEFAULT 'FCL',status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,reviewed_at TEXT,revision INTEGER NOT NULL DEFAULT 0,requirements TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,name TEXT NOT NULL,ext TEXT NOT NULL,size INTEGER NOT NULL,hash TEXT NOT NULL,path TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'uploaded',type TEXT NOT NULL DEFAULT 'Other',type_verified INTEGER NOT NULL DEFAULT 0,classification_evidence TEXT NOT NULL DEFAULT '',error TEXT,reading_method TEXT,elapsed REAL,UNIQUE(case_id,hash));
CREATE TABLE IF NOT EXISTS pages(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,number INTEGER NOT NULL,text TEXT NOT NULL,method TEXT NOT NULL,quality TEXT NOT NULL,table_json TEXT NOT NULL DEFAULT '[]',UNIQUE(document_id,number));
CREATE TABLE IF NOT EXISTS bundle_sources(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,name TEXT NOT NULL,hash TEXT NOT NULL,path TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS document_sources(document_id TEXT PRIMARY KEY REFERENCES documents(id) ON DELETE CASCADE,source_id TEXT NOT NULL REFERENCES bundle_sources(id),start_page INTEGER NOT NULL,end_page INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,document_id TEXT REFERENCES documents(id) ON DELETE CASCADE,kind TEXT NOT NULL,key TEXT NOT NULL,raw_json TEXT NOT NULL,value_json TEXT NOT NULL,page INTEGER,evidence TEXT NOT NULL,method TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',note TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS revisions(id TEXT PRIMARY KEY,record_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE,before_json TEXT NOT NULL,after_json TEXT NOT NULL,actor TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checks(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,key TEXT NOT NULL,result TEXT NOT NULL,severity TEXT NOT NULL,detail_json TEXT NOT NULL,resolution TEXT NOT NULL DEFAULT '',UNIQUE(case_id,key));
CREATE TABLE IF NOT EXISTS exports(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE,created_at TEXT NOT NULL,version INTEGER NOT NULL,mode TEXT NOT NULL,workbook_type TEXT NOT NULL,path TEXT NOT NULL,case_revision INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_cache(hash TEXT PRIMARY KEY,payload TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_usage(id TEXT PRIMARY KEY,case_id TEXT,created_at TEXT NOT NULL,model TEXT NOT NULL,input_tokens INTEGER,output_tokens INTEGER,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS templates(id TEXT PRIMARY KEY,name TEXT NOT NULL,path TEXT NOT NULL,sheets_json TEXT NOT NULL,mapping_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,case_id TEXT,created_at TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,entity TEXT NOT NULL,before_json TEXT,after_json TEXT,reason TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_records_case ON records(case_id);
CREATE INDEX IF NOT EXISTS idx_docs_case ON documents(case_id);
CREATE INDEX IF NOT EXISTS idx_audit_case ON audit(case_id,created_at);
